 "content": "def transform(grid):
    if not grid or not grid[0]:
        return [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Find the background color (the most frequent color), then recolor only
    # complete rows/columns of the other color(s) to their successor.
    from collections import Counter
    background = Counter(x for row in grid for x in row).most_common(1)[0][0]
    marked = set()
    for r, row in enumerate(grid):
        if row[0] != background and all(x == row[0] for x in row):
            marked.update((r, c) for c in range(w))
    for c in range(w):
        value = grid[0][c]
        if value != background and all(grid[r][c] == value for r in range(h)):
            marked.update((r, c) for r in range(h))
    out = [row[:] for row in grid]
    for r, c in marked:
        out[r][c] = (out[r][c] + 1) % 10
    return out
